import statistics


def covariance(xs, ys):
    mx = sum(xs) / len(xs)
    my = sum(ys) / len(ys)
    return sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / len(xs)


def correlation(xs, ys):
    return round(covariance(xs, ys) / (statistics.pstdev(xs) * statistics.pstdev(ys)), 3)


def plus_liee(cible, variables):
    nom = max(variables, key=lambda n: abs(correlation(variables[n], cible)))
    return [nom, correlation(variables[nom], cible)]
